30	 * kernel execution with device/host memcopies.  The kernel computes an
31	 * element-wise square of a float array, after which the result is copied
32	 * back to host (CPU) memory.  To increase performance, multiple
33	 * kernel/memcopy pairs are launched asynchronously, each pair in its
34	 * own stream.  A GPU can overlap a kernel and a memcopy as long as they
35	 * are issued in different streams.  Thus, if n pairs are launched, the
36	 * streamed approach can reduce the memcopy cost to the (1/n)th of a
37	 * single copy of the entire data set.
38	 *
39	 * Additionally, this sample uses CUDA events to measure elapsed time for
40	 * CUDA calls.  Events are a part of CUDA API and provide a system independent
41	 * way to measure execution times on CUDA devices with approximately 0.5
42	 * microsecond precision.
43	 *
44	 */
45	
46	// System includes
47	#include <stdio.h>
48	
49	// CUDA runtime
50	#include <cuda_runtime.h>
51	
52	#define N (1 << 24) // ~16M elements
53	#define BLOCK 256   // threads per block
54	#define NUM_STREAMS 4   // number of concurrent streams
55	
56	// Kernel: computes element-wise square of the input array
57	__global__ void square_kernel(const float* in, float* out, int n){
58	    int idx = blockIdx.x * blockDim.x + threadIdx.x;
59	    if (idx < n){
60	        out[idx] = in[idx] * in[idx];
61	    }
62	}
63	
64	// Run the full H2D memcopy + kernel + D2H memcopy in a single default stream.
65	// Returns elapsed time in milliseconds.
66	float run_default_stream(float* h_in, float* h_out, int n){
67	    float *d_in, *d_out;  // device input and output buffers
68	    size_t bytes = n * sizeof(float);
69	
70	    // allocate device memory
71	    cudaMalloc(&d_in, bytes);
72	    cudaMalloc(&d_out, bytes);
73	
74	    // create CUDA event handles for timing
75	    cudaEvent_t start, stop;
76	    cudaEventCreate(&start);
77	    cudaEventCreate(&stop);
78	
79	    cudaEventRecord(start);
80	
81	    // copy input to device, run kernel, copy result back
82	    cudaMemcpy(d_in, h_in, bytes, cudaMemcpyHostToDevice);
83	    int grid = (n + BLOCK - 1) / BLOCK;
84	    square_kernel<<<grid, BLOCK>>>(d_in, d_out, n);
85	    cudaMemcpy(h_out, d_out, bytes, cudaMemcpyDeviceToHost);
86	
87	    cudaEventRecord(stop);
88	    cudaEventSynchronize(stop); // block until the event is actually recorded
89	
90	    float ms;
91	    cudaEventElapsedTime(&ms, start, stop);
92	
93	    // release device resources
94	    cudaFree(d_in);
95	    cudaFree(d_out);
96	    cudaEventDestroy(start);
97	    cudaEventDestroy(stop);
98	
99	    return ms;
100	}
101	
102	// Run the same workload split across 4 streams so that H2D memcopies,
103	// kernel execution, and D2H memcopies can overlap on the device.
104	// Returns elapsed time in milliseconds.
105	float run_multi_stream(float* h_in, float* h_out, int n){
106	    int chunk = n/NUM_STREAMS;                      // number of elements per stream
107	    size_t chunk_bytes = chunk * sizeof(float);
108	
109	    float *d_in[NUM_STREAMS], *d_out[NUM_STREAMS]; // per-stream device buffers
110	    cudaStream_t streams[NUM_STREAMS];
111	
112	    // allocate and initialize an array of stream handles
113	    for(int i = 0; i < NUM_STREAMS; i++){
114	        cudaStreamCreateWithFlags(&streams[i], cudaStreamNonBlocking);
115	        cudaMalloc(&d_in[i], chunk_bytes);
116	        cudaMalloc(&d_out[i], chunk_bytes);
117	    }
118	
119	    // create CUDA event handles for timing
120	    cudaEvent_t start, stop;
121	    cudaEventCreate(&start);
122	    cudaEventCreate(&stop);
123	
124	    cudaEventRecord(start, streams[0]);
125	
126	    // asynchronously launch 4 copies + kernels + copies, each in its own
127	    // stream so they can overlap on the device
128	    for(int i = 0; i < NUM_STREAMS; i++){
129	        int offset = i * chunk; // element offset into the host arrays for this stream
130	
131	        // H2D: copy this stream's chunk to device (non-blocking on host)
132	        cudaMemcpyAsync(
133	            d_in[i],
134	            h_in + offset,
135	            chunk_bytes,
136	            cudaMemcpyHostToDevice,
137	            streams[i]
138	        );
139	
140	        // kernel: will only start after the H2D copy in this stream completes
141	        int grid = (chunk + BLOCK - 1) / BLOCK;
142	        square_kernel<<<grid, BLOCK, 0, streams[i]>>>(
143	            d_in[i], d_out[i], chunk
144	        );
145	
146	        // D2H: copy result back; starts after the kernel in this stream finishes
147	        cudaMemcpyAsync(
148	            h_out + offset,
149	            d_out[i],
150	            chunk_bytes,
151	            cudaMemcpyDeviceToHost,
152	            streams[i]
153	        );
154	    }
155	
156	    // Wait for all streams to complete their work
157	    for(int i=0; i < NUM_STREAMS; i++) { 
158	       cudaStreamSynchronize(streams[i]);
159	     }
160	    cudaEventRecord(stop, streams[0]);
161	
162	    // Sync with stream 0, which only completes once all other work
163	    // is done and the stop event is recorded
164	    cudaStreamSynchronize(streams[0]);
165	
166	    float ms;
167	    cudaEventElapsedTime(&ms, start, stop);
168	
169	    // release per-stream resources
170	    for(int i=0; i < NUM_STREAMS; i++){
171	        cudaFree(d_in[i]);
172	        cudaFree(d_out[i]);
173	        cudaStreamDestroy(streams[i]);
174	    }
175	
176	    cudaEventDestroy(start);
177	    cudaEventDestroy(stop);
178	
179	    return ms;
180	}
