28	/*
29	    Parallel reduction
30	
31	    This sample shows how to perform a reduction operation on an array of values
32	    to produce a single value.
33	
34	    Reductions are a very common computation in parallel algorithms.  Any time
35	    an array of values needs to be reduced to a single value using a binary
36	    associative operator, a reduction can be used.  Example applications include
37	    statistics computations such as mean and standard deviation, and image
38	    processing applications such as finding the total luminance of an
39	    image.
40	
41	    This code performs sum reductions, but any associative operator such as
42	    min() or max() could also be used.
43	
44	    It assumes the input size is a power of 2.
45	
46	    COMMAND LINE ARGUMENTS
47	
48	    "--shmoo":         Test performance for 1 to 32M elements with each of the 7
49	   different kernels
50	    "--n=<N>":         Specify the number of elements to reduce (default
51	   1048576)
52	    "--threads=<N>":   Specify the number of threads per block (default 128)
53	    "--kernel=<N>":    Specify which kernel to run (0-6, default 6)
54	    "--maxblocks=<N>": Specify the maximum number of thread blocks to launch
55	   (kernel 6 only, default 64)
56	    "--cpufinal":      Read back the per-block results and do final sum of block
57	   sums on CPU (default false)
58	    "--cputhresh=<N>": The threshold of number of blocks sums below which to
59	   perform a CPU final reduction (default 1)
60	    "-type=<T>":       The datatype for the reduction, where T is "int",
61	   "float", or "double" (default int)
62	*/
63	
64	// CUDA Runtime
65	#include <cuda_runtime.h>
66	
67	// Utilities and system includes
68	#include <algorithm>
69	#include <helper_cuda.h>
70	#include <helper_functions.h>
71	
72	// includes, project
73	#include "reduction.h"
74	
75	enum ReduceType { REDUCE_INT, REDUCE_FLOAT, REDUCE_DOUBLE };
76	
77	////////////////////////////////////////////////////////////////////////////////
78	// declaration, forward
79	template <class T> bool runTest(int argc, char **argv, ReduceType datatype);
80	
81	#define MAX_BLOCK_DIM_SIZE 65535
82	
83	#ifdef WIN32
84	#define strcasecmp strcmpi
85	#endif
86	
87	extern "C" bool isPow2(unsigned int x) { return ((x & (x - 1)) == 0); }
88	
89	const char *getReduceTypeString(const ReduceType type)
90	{
91	    switch (type) {
92	    case REDUCE_INT:
93	        return "int";
94	    case REDUCE_FLOAT:
95	        return "float";
96	    case REDUCE_DOUBLE:
97	        return "double";
98	    default:
99	        return "unknown";
100	    }
101	}
102	
103	////////////////////////////////////////////////////////////////////////////////
104	// Program main
105	////////////////////////////////////////////////////////////////////////////////
106	int main(int argc, char **argv)
107	{
108	    printf("%s Starting...\n\n", argv[0]);
109	
110	    char *typeInput = 0;
111	    getCmdLineArgumentString(argc, (const char **)argv, "type", &typeInput);
112	
113	    ReduceType datatype = REDUCE_INT;
114	
115	    if (0 != typeInput) {
116	        if (!strcasecmp(typeInput, "float")) {
117	            datatype = REDUCE_FLOAT;
118	        }
119	        else if (!strcasecmp(typeInput, "double")) {
120	            datatype = REDUCE_DOUBLE;
121	        }
122	        else if (strcasecmp(typeInput, "int")) {
123	            printf("Type %s is not recognized. Using default type int.\n\n", typeInput);
124	        }
125	    }
126	
127	    cudaDeviceProp deviceProp;
128	    int            dev;
129	
130	    dev = findCudaDevice(argc, (const char **)argv);
131	
132	    checkCudaErrors(cudaGetDeviceProperties(&deviceProp, dev));
133	
134	    printf("Using Device %d: %s\n\n", dev, deviceProp.name);
135	    checkCudaErrors(cudaSetDevice(dev));
136	
137	    printf("Reducing array of type %s\n\n", getReduceTypeString(datatype));
138	
139	    bool bResult = false;
140	
141	    switch (datatype) {
142	    default:
143	    case REDUCE_INT:
144	        bResult = runTest<int>(argc, argv, datatype);
145	        break;
146	
147	    case REDUCE_FLOAT:
148	        bResult = runTest<float>(argc, argv, datatype);
149	        break;
150	
151	    case REDUCE_DOUBLE:
152	        bResult = runTest<double>(argc, argv, datatype);
153	        break;
154	    }
155	
156	    printf(bResult ? "Test passed\n" : "Test failed!\n");
157	}
158	
159	////////////////////////////////////////////////////////////////////////////////
160	//! Compute sum reduction on CPU
161	//! We use Kahan summation for an accurate sum of large arrays.
162	//! http://en.wikipedia.org/wiki/Kahan_summation_algorithm
163	//!
164	//! @param data       pointer to input data
165	//! @param size       number of input data elements
166	////////////////////////////////////////////////////////////////////////////////
167	template <class T> T reduceCPU(T *data, int size)
168	{
169	    T sum = data[0];
170	    T c   = (T)0.0;
171	
172	    for (int i = 1; i < size; i++) {
173	        T y = data[i] - c;
174	        T t = sum + y;
175	        c   = (t - sum) - y;
176	        sum = t;
177	    }
178	
179	    return sum;
180	}
181	
182	unsigned int nextPow2(unsigned int x)
183	{
184	    --x;
185	    x |= x >> 1;
186	    x |= x >> 2;
187	    x |= x >> 4;
188	    x |= x >> 8;
189	    x |= x >> 16;
190	    return ++x;
191	}
192	
193	#ifndef MIN
194	#define MIN(x, y) ((x < y) ? x : y)
195	#endif
196	
197	////////////////////////////////////////////////////////////////////////////////
198	// Compute the number of threads and blocks to use for the given reduction
199	// kernel For the kernels >= 3, we set threads / block to the minimum of
200	// maxThreads and n/2. For kernels < 3, we set to the minimum of maxThreads and
201	// n.  For kernel 6, we observe the maximum specified number of blocks, because
202	// each thread in that kernel can process a variable number of elements.
203	////////////////////////////////////////////////////////////////////////////////
204	void getNumBlocksAndThreads(int whichKernel, int n, int maxBlocks, int maxThreads, int &blocks, int &threads)
205	{
206	    // get device capability, to avoid block/grid size exceed the upper bound
207	    cudaDeviceProp prop;
208	    int            device;
209	    checkCudaErrors(cudaGetDevice(&device));
210	    checkCudaErrors(cudaGetDeviceProperties(&prop, device));
211	
212	    if (whichKernel < 3) {
213	        threads = (n < maxThreads) ? nextPow2(n) : maxThreads;
214	        blocks  = (n + threads - 1) / threads;
215	    }
216	    else {
217	        threads = (n < maxThreads * 2) ? nextPow2((n + 1) / 2) : maxThreads;
218	        blocks  = (n + (threads * 2 - 1)) / (threads * 2);
219	    }
220	
221	    if ((float)threads * blocks > (float)prop.maxGridSize[0] * prop.maxThreadsPerBlock) {
222	        printf("n is too large, please choose a smaller number!\n");
223	    }
224	
225	    if (blocks > prop.maxGridSize[0]) {
226	        printf("Grid size <%d> exceeds the device capability <%d>, set block size as "
227	               "%d (original %d)\n",
228	               blocks,
229	               prop.maxGridSize[0],
230	               threads * 2,
231	               threads);
232	
233	        blocks /= 2;
234	        threads *= 2;
235	    }
236	
237	    if (whichKernel >= 6) {
238	        blocks = MIN(maxBlocks, blocks);
239	    }
240	}
241	
242	////////////////////////////////////////////////////////////////////////////////
243	// This function performs a reduction of the input data multiple times and
244	// measures the average reduction time.
245	////////////////////////////////////////////////////////////////////////////////
246	template <class T>
247	T benchmarkReduce(int                 n,
248	                  int                 numThreads,
249	                  int                 numBlocks,
250	                  int                 maxThreads,
251	                  int                 maxBlocks,
252	                  int                 whichKernel,
253	                  int                 testIterations,
254	                  bool                cpuFinalReduction,
255	                  int                 cpuFinalThreshold,
256	                  StopWatchInterface *timer,
257	                  T                  *h_odata,
258	                  T                  *d_idata,
259	                  T                  *d_odata)
260	{
261	    T    gpu_result   = 0;
262	    bool needReadBack = true;
263	
264	    T *d_intermediateSums;
265	    checkCudaErrors(cudaMalloc((void **)&d_intermediateSums, sizeof(T) * numBlocks));
266	
267	    for (int i = 0; i < testIterations; ++i) {
268	        gpu_result = 0;
269	
270	        cudaDeviceSynchronize();
271	        sdkStartTimer(&timer);
272	
273	        // execute the kernel
274	        reduce<T>(n, numThreads, numBlocks, whichKernel, d_idata, d_odata);
275	
276	        // check if kernel execution generated an error
277	        getLastCudaError("Kernel execution failed");
278	
279	        if (cpuFinalReduction) {
280	            // sum partial sums from each block on CPU
281	            // copy result from device to host
282	            checkCudaErrors(cudaMemcpy(h_odata, d_odata, numBlocks * sizeof(T), cudaMemcpyDeviceToHost));
283	
284	            for (int i = 0; i < numBlocks; i++) {
285	                gpu_result += h_odata[i];
286	            }
287	
288	            needReadBack = false;
289	        }
290	        else {
291	            // sum partial block sums on GPU
292	            int s      = numBlocks;
293	            int kernel = whichKernel;
294	
295	            while (s > cpuFinalThreshold) {
296	                int threads = 0, blocks = 0;
297	                getNumBlocksAndThreads(kernel, s, maxBlocks, maxThreads, blocks, threads);
298	                checkCudaErrors(cudaMemcpy(d_intermediateSums, d_odata, s * sizeof(T), cudaMemcpyDeviceToDevice));
299	                reduce<T>(s, threads, blocks, kernel, d_intermediateSums, d_odata);
300	
301	                if (kernel < 3) {
302	                    s = (s + threads - 1) / threads;
303	                }
304	                else {
305	                    s = (s + (threads * 2 - 1)) / (threads * 2);
306	                }
307	            }
308	
309	            if (s > 1) {
310	                // copy result from device to host
311	                checkCudaErrors(cudaMemcpy(h_odata, d_odata, s * sizeof(T), cudaMemcpyDeviceToHost));
312	
313	                for (int i = 0; i < s; i++) {
314	                    gpu_result += h_odata[i];
315	                }
316	
317	                needReadBack = false;
318	            }
319	        }
320	
321	        cudaDeviceSynchronize();
322	        sdkStopTimer(&timer);
323	    }
324	
325	    if (needReadBack) {
326	        // copy final sum from device to host
327	        checkCudaErrors(cudaMemcpy(&gpu_result, d_odata, sizeof(T), cudaMemcpyDeviceToHost));
328	    }
329	    checkCudaErrors(cudaFree(d_intermediateSums));
330	    return gpu_result;
331	}
332	
333	////////////////////////////////////////////////////////////////////////////////
334	// This function calls benchmarkReduce multiple times for a range of array sizes
335	// and prints a report in CSV (comma-separated value) format that can be used
336	// for generating a "shmoo" plot showing the performance for each kernel
337	// variation over a wide range of input sizes.
338	////////////////////////////////////////////////////////////////////////////////
339	template <class T> void shmoo(int minN, int maxN, int maxThreads, int maxBlocks, ReduceType datatype)
340	{
341	    // create random input data on CPU
342	    unsigned int bytes = maxN * sizeof(T);
343	
344	    T *h_idata = (T *)malloc(bytes);
345	
346	    for (int i = 0; i < maxN; i++) {
347	        // Keep the numbers small so we don't get truncation error in the sum
348	        if (datatype == REDUCE_INT) {
349	            h_idata[i] = (T)(rand() & 0xFF);
350	        }
351	        else {
352	            h_idata[i] = (rand() & 0xFF) / (T)RAND_MAX;
353	        }
354	    }
355	
356	    int maxNumBlocks = MIN(maxN / maxThreads, MAX_BLOCK_DIM_SIZE);
357	
358	    // allocate mem for the result on host side
359	    T *h_odata = (T *)malloc(maxNumBlocks * sizeof(T));
360	
361	    // allocate device memory and data
362	    T *d_idata = NULL;
363	    T *d_odata = NULL;
364	
365	    checkCudaErrors(cudaMalloc((void **)&d_idata, bytes));
366	    checkCudaErrors(cudaMalloc((void **)&d_odata, maxNumBlocks * sizeof(T)));
367	
368	    // copy data directly to device memory
369	    checkCudaErrors(cudaMemcpy(d_idata, h_idata, bytes, cudaMemcpyHostToDevice));
370	    checkCudaErrors(cudaMemcpy(d_odata, h_idata, maxNumBlocks * sizeof(T), cudaMemcpyHostToDevice));
371	
372	    // warm-up
373	    for (int kernel = 0; kernel < 8; kernel++) {
374	        reduce<T>(maxN, maxThreads, maxNumBlocks, kernel, d_idata, d_odata);
375	    }
376	
377	    int testIterations = 100;
378	
379	    StopWatchInterface *timer = 0;
380	    sdkCreateTimer(&timer);
381	
382	    // print headers
383	    printf("Time in milliseconds for various numbers of elements for each "
384	           "kernel\n\n\n");
385	    printf("Kernel");
386	
387	    for (int i = minN; i <= maxN; i *= 2) {
388	        printf(", %d", i);
389	    }
390	
391	    for (int kernel = 0; kernel < 8; kernel++) {
392	        printf("\n%d", kernel);
393	
394	        for (int i = minN; i <= maxN; i *= 2) {
395	            sdkResetTimer(&timer);
396	            int numBlocks  = 0;
397	            int numThreads = 0;
398	            getNumBlocksAndThreads(kernel, i, maxBlocks, maxThreads, numBlocks, numThreads);
399	
400	            float reduceTime;
401	
402	            if (numBlocks <= MAX_BLOCK_DIM_SIZE) {
403	                benchmarkReduce(i,
404	                                numThreads,
405	                                numBlocks,
406	                                maxThreads,
407	                                maxBlocks,
408	                                kernel,
409	                                testIterations,
410	                                false,
411	                                1,
412	                                timer,
413	                                h_odata,
414	                                d_idata,
415	                                d_odata);
416	                reduceTime = sdkGetAverageTimerValue(&timer);
417	            }
418	            else {
419	                reduceTime = -1.0;
420	            }
421	
422	            printf(", %.5f", reduceTime);
423	        }
424	    }
425	
426	    // cleanup
427	    sdkDeleteTimer(&timer);
428	    free(h_idata);
429	    free(h_odata);
430	
431	    checkCudaErrors(cudaFree(d_idata));
432	    checkCudaErrors(cudaFree(d_odata));
433	}
434	
435	////////////////////////////////////////////////////////////////////////////////
436	// The main function which runs the reduction test.
437	////////////////////////////////////////////////////////////////////////////////
438	template <class T> bool runTest(int argc, char **argv, ReduceType datatype)
439	{
440	    int  size              = 1 << 24; // number of elements to reduce
441	    int  maxThreads        = 256;     // number of threads per block
442	    int  whichKernel       = 7;
443	    int  maxBlocks         = 64;
444	    bool cpuFinalReduction = false;
445	    int  cpuFinalThreshold = 1;
446	
447	    if (checkCmdLineFlag(argc, (const char **)argv, "n")) {
448	        size = getCmdLineArgumentInt(argc, (const char **)argv, "n");
449	    }
450	
451	    if (checkCmdLineFlag(argc, (const char **)argv, "threads")) {
452	        maxThreads = getCmdLineArgumentInt(argc, (const char **)argv, "threads");
453	    }
454	
455	    if (checkCmdLineFlag(argc, (const char **)argv, "kernel")) {
456	        whichKernel = getCmdLineArgumentInt(argc, (const char **)argv, "kernel");
457	    }
458	
459	    if (checkCmdLineFlag(argc, (const char **)argv, "maxblocks")) {
460	        maxBlocks = getCmdLineArgumentInt(argc, (const char **)argv, "maxblocks");
461	    }
462	
463	    printf("%d elements\n", size);
464	    printf("%d threads (max)\n", maxThreads);
465	
466	    cpuFinalReduction = checkCmdLineFlag(argc, (const char **)argv, "cpufinal");
467	
468	    if (checkCmdLineFlag(argc, (const char **)argv, "cputhresh")) {
469	        cpuFinalThreshold = getCmdLineArgumentInt(argc, (const char **)argv, "cputhresh");
470	    }
471	
472	    bool runShmoo = checkCmdLineFlag(argc, (const char **)argv, "shmoo");
473	
474	    if (runShmoo) {
475	        shmoo<T>(1, 33554432, maxThreads, maxBlocks, datatype);
476	    }
477	    else {
478	        // create random input data on CPU
479	        unsigned int bytes = size * sizeof(T);
480	
481	        T *h_idata = (T *)malloc(bytes);
482	
483	        for (int i = 0; i < size; i++) {
484	            // Keep the numbers small so we don't get truncation error in the sum
485	            if (datatype == REDUCE_INT) {
486	                h_idata[i] = (T)(rand() & 0xFF);
487	            }
488	            else {
489	                h_idata[i] = (rand() & 0xFF) / (T)RAND_MAX;
490	            }
491	        }
492	
493	        int numBlocks  = 0;
494	        int numThreads = 0;
495	        getNumBlocksAndThreads(whichKernel, size, maxBlocks, maxThreads, numBlocks, numThreads);
496	
497	        if (numBlocks == 1) {
498	            cpuFinalThreshold = 1;
499	        }
500	
501	        // allocate mem for the result on host side
502	        T *h_odata = (T *)malloc(numBlocks * sizeof(T));
503	
504	        printf("%d blocks\n\n", numBlocks);
505	
506	        // allocate device memory and data
507	        T *d_idata = NULL;
508	        T *d_odata = NULL;
509	
510	        checkCudaErrors(cudaMalloc((void **)&d_idata, bytes));
511	        checkCudaErrors(cudaMalloc((void **)&d_odata, numBlocks * sizeof(T)));
512	
513	        // copy data directly to device memory
514	        checkCudaErrors(cudaMemcpy(d_idata, h_idata, bytes, cudaMemcpyHostToDevice));
515	        checkCudaErrors(cudaMemcpy(d_odata, h_idata, numBlocks * sizeof(T), cudaMemcpyHostToDevice));
516	
517	        // warm-up
518	        reduce<T>(size, numThreads, numBlocks, whichKernel, d_idata, d_odata);
519	
520	        int testIterations = 100;
521	
522	        StopWatchInterface *timer = 0;
523	        sdkCreateTimer(&timer);
524	
525	        T gpu_result = 0;
526	
527	        gpu_result = benchmarkReduce<T>(size,
528	                                        numThreads,
529	                                        numBlocks,
530	                                        maxThreads,
531	                                        maxBlocks,
532	                                        whichKernel,
533	                                        testIterations,
534	                                        cpuFinalReduction,
535	                                        cpuFinalThreshold,
536	                                        timer,
537	                                        h_odata,
538	                                        d_idata,
539	                                        d_odata);
540	
541	        double reduceTime = sdkGetAverageTimerValue(&timer) * 1e-3;
542	        printf("Reduction, Throughput = %.4f GB/s, Time = %.5f s, Size = %u Elements, "
543	               "NumDevsUsed = %d, Workgroup = %u\n",
544	               1.0e-9 * ((double)bytes) / reduceTime,
545	               reduceTime,
546	               size,
547	               1,
548	               numThreads);
549	
550	        // compute reference solution
551	        T cpu_result = reduceCPU<T>(h_idata, size);
552	
553	        int    precision = 0;
554	        double threshold = 0;
555	        double diff      = 0;
556	
557	        if (datatype == REDUCE_INT) {
558	            printf("\nGPU result = %d\n", (int)gpu_result);
559	            printf("CPU result = %d\n\n", (int)cpu_result);
560	        }
561	        else {
562	            if (datatype == REDUCE_FLOAT) {
563	                precision = 8;
564	                threshold = 1e-8 * size;
565	            }
566	            else {
567	                precision = 12;
568	                threshold = 1e-12 * size;
569	            }
570	
571	            printf("\nGPU result = %.*f\n", precision, (double)gpu_result);
572	            printf("CPU result = %.*f\n\n", precision, (double)cpu_result);
573	
574	            diff = fabs((double)gpu_result - (double)cpu_result);
575	        }
576	
577	        // cleanup
578	        sdkDeleteTimer(&timer);
579	        free(h_idata);
580	        free(h_odata);
581	
582	        checkCudaErrors(cudaFree(d_idata));
583	        checkCudaErrors(cudaFree(d_odata));
584	
585	        if (datatype == REDUCE_INT) {
586	            return (gpu_result == cpu_result);
587	        }
588	        else {
589	            return (diff < threshold);
590	        }
591	    }
592	
593	    return true;
594	}
