// Multi stream: a sliding window of at most numStreams chunks in flight.
// Chunks are assigned round-robin so each stream keeps its own buffers; a
// buffer is reused only after the previous chunk on that stream has been
// copied back and verified.
static RunStatus run_multi(Context* ctx, long long n, long long round,
                           float* msOut)
{
    int S = ctx->numStreams;
    long long numChunks = (n + ctx->chunk - 1) / ctx->chunk;

    long long slotChunk[STACKS_MAX]; // chunk currently occupying slot s
    for (int s = 0; s < S; ++s)
        slotChunk[s] = -1;

    if (!cuda_ok(cudaEventRecord(ctx->startEv, ctx->streams[0]),
                 "recording start event"))
        return RUN_CUDA_ERROR;

    long long next = 0; // next chunk not yet submitted

    // Prime the pipeline with one chunk per stream (or fewer if there are
    // fewer chunks than streams).
    while (next < numChunks && next < S) {
        int s = (int)next;
        bool lastForStream = (next + S >= numChunks);
        if (!submit_chunk(ctx, s, next, n, round, lastForStream)) {
            drain_all(ctx);
            return RUN_CUDA_ERROR;
        }
        slotChunk[s] = next;
        ++next;
    }

    long long completed = 0;
    RunStatus status = RUN_OK;

    while (completed < numChunks) {
        bool progressed = false;
        for (int s = 0; s < S && completed < numChunks; ++s) {
            if (slotChunk[s] < 0)
                continue;

            cudaError_t q = cudaStreamQuery(ctx->streams[s]);
            if (q == cudaErrorNotReady)
                continue;
            if (q != cudaSuccess) {
                fprintf(stderr, "CUDA error while waiting for chunk %lld: "
                        "%s (%s)\n",
                        slotChunk[s], cudaGetErrorString(q),
                        cudaGetErrorName(q));
                drain_all(ctx);
                return RUN_CUDA_ERROR;
            }

            // D2H finished: read and verify before reusing the buffers.
            long long c = slotChunk[s];
            int cnt = chunk_count(n, ctx->chunk, c);
            long long bad;
            float expected, actual;
            if (!verify_chunk(ctx->h_out[s], c * ctx->chunk, cnt, round,
                              "Multi-stream", &bad, &expected, &actual)) {
                drain_all(ctx);
                return RUN_MISMATCH;
            }
            slotChunk[s] = -1;
            ++completed;
            progressed = true;

            if (next < numChunks) {
                bool lastForStream = (next + S >= numChunks);
                if (!submit_chunk(ctx, s, next, n, round, lastForStream)) {
                    drain_all(ctx);
                    return RUN_CUDA_ERROR;
                }
                slotChunk[s] = next;
                ++next;
            }
        }
        if (!progressed)
            sched_yield(); // all in-flight chunks still running
    }

    // Every stream's last D2H is marked by endEv[s]; the round ends when the
    // last of them completes, so take the maximum elapsed time.
    float maxMs = 0.0f;
    int usedStreams = (numChunks < S) ? (int)numChunks : S;
    for (int s = 0; s < usedStreams; ++s) {
        if (!cuda_ok(cudaEventSynchronize(ctx->endEv[s]),
                     "synchronizing end event"))
            return RUN_CUDA_ERROR;
        float ms;
        if (!cuda_ok(cudaEventElapsedTime(&ms, ctx->startEv, ctx->endEv[s]),
                     "measuring elapsed time"))
            return RUN_CUDA_ERROR;
        if (ms > maxMs)
            maxMs = ms;
    }
    (void)status;
    *msOut = maxMs;
    return RUN_OK;
}

