193	// Reusable per-stream resources.  All working memory scales with chunk and
194	// streams only, never with n or repeat.
195	struct Context {
196	    int          numStreams;
197	    long long    chunk;
198	    cudaStream_t streams[STREAMS_MAX];
199	    cudaEvent_t  startEv;                 // first H2D of a round
200	    cudaEvent_t  endEv[STREAMS_MAX];      // last D2H per stream in a round
201	    float*       d_in[STREAMS_MAX];
202	    float*       d_out[STREAMS_MAX];
203	    float*       h_in[STREAMS_MAX];       // pinned, chunk floats each
204	    float*       h_out[STREAMS_MAX];      // pinned, chunk floats each
205	};
206	
207	static bool setup_context(const Options& opt, Context* ctx)
208	{
209	    memset(ctx, 0, sizeof(*ctx));
210	    ctx->numStreams = (int)opt.streams;
211	    ctx->chunk      = opt.chunk;
212	
213	    size_t chunkBytes = (size_t)opt.chunk * sizeof(float);
214	
215	    for (int s = 0; s < ctx->numStreams; ++s) {
216	        if (!cuda_ok(cudaStreamCreateWithFlags(&ctx->streams[s],
217	                                               cudaStreamNonBlocking),
218	                     "creating stream"))
219	            return false;
220	        if (!cuda_ok(cudaEventCreate(&ctx->endEv[s]), "creating event"))
221	            return false;
222	        if (!cuda_ok(cudaMalloc(&ctx->d_in[s], chunkBytes),
223	                     "allocating device input buffer"))
224	            return false;
225	        if (!cuda_ok(cudaMalloc(&ctx->d_out[s], chunkBytes),
226	                     "allocating device output buffer"))
227	            return false;
228	        if (!cuda_ok(cudaMallocHost(&ctx->h_in[s], chunkBytes),
229	                     "allocating pinned host input buffer"))
230	            return false;
231	        if (!cuda_ok(cudaMallocHost(&ctx->h_out[s], chunkBytes),
232	                     "allocating pinned host output buffer"))
233	            return false;
234	    }
235	    if (!cuda_ok(cudaEventCreate(&ctx->startEv), "creating event"))
236	        return false;
237	    return true;
238	}
