240	static void teardown_context(Context* ctx)
241	{
242	    // Make sure no work is still in flight before freeing anything.
243	    for (int s = 0; s < ctx->numStreams; ++s) {
244	        if (ctx->streams[s])
245	            (void)cudaStreamSynchronize(ctx->streams[s]);
246	    }
247	    for (int s = 0; s < ctx->numStreams; ++s) {
